// AUTO-GENERATED — do not edit by hand.
// 256x128 equirectangular boolean land/water mask for the home globe (D-10).
// Derived (downsampled to 256x128 + luminance-thresholded) from three-globe's
// earth-water.png, itself based on NASA / Natural Earth public-domain map data.
// This is factual coastline data (land vs water), used display-only — never for
// correctness (same line as lib/ixdtf/tokenize.ts).

export const MASK_W = 256;
export const MASK_H = 128;

const PACKED =
  "";

// Decode the base64 bitset once at module load (browser `atob`, also in Node 18+).
const BITS: Uint8Array = (() => {
  const bin = atob(PACKED);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
})();

/** True when the given lat/lng (degrees) falls on land. */
export function isLandAt(lat: number, lng: number): boolean {
  const x = Math.min(MASK_W - 1, Math.max(0, Math.round(((lng + 180) / 360) * MASK_W)));
  const y = Math.min(MASK_H - 1, Math.max(0, Math.round(((90 - lat) / 180) * MASK_H)));
  const idx = y * MASK_W + x;
  return (BITS[idx >> 3] & (1 << (idx & 7))) !== 0;
}
